1	/**
2	 * Migration smoke test — guards three contracts:
3	 *   1. Every Drizzle SQL file under `drizzle/` has a matching entry in
4	 *      `drizzle/meta/_journal.json`. PDD-008 (orphan migrations are
5	 *      silently skipped) requires this pairing.
6	 *   2. The Zapier migration (0356) is journaled.
7	 *   3. The migration is idempotent at the SQL-text level: every
8	 *      `CREATE TABLE` / `CREATE INDEX` uses `IF NOT EXISTS`, and the seed
9	 *      uses `ON CONFLICT ... DO NOTHING`.
10	 *
11	 * Runs against the on-disk files only — no DB connection required.
12	 */
13	
14	import * as fs from 'node:fs';
15	import * as path from 'node:path';
16	
17	const DRIZZLE_DIR = path.join(process.cwd(), 'drizzle');
18	const JOURNAL_PATH = path.join(DRIZZLE_DIR, 'meta', '_journal.json');
19	const MIGRATION_FILE = '0356_zapier_oauth.sql';
20	
21	interface JournalEntry {
22	  idx: number;
23	  version: string;
24	  when: number;
25	  tag: string;
26	  breakpoints: boolean;
27	}
28	
29	function loadJournal(): { entries: JournalEntry[] } {
30	  return JSON.parse(fs.readFileSync(JOURNAL_PATH, 'utf-8'));
31	}
32	
33	describe('drizzle/0356_zapier_oauth migration', () => {
34	  it('file exists on disk', () => {
35	    expect(fs.existsSync(path.join(DRIZZLE_DIR, MIGRATION_FILE))).toBe(true);
36	  });
37	
38	  it('has a corresponding entry in _journal.json (PDD-008)', () => {
39	    const journal = loadJournal();
40	    const entry = journal.entries.find((e) => e.tag === '0356_zapier_oauth');
41	    expect(entry).toBeDefined();
42	    expect(entry?.idx).toBe(356);
43	    expect(entry?.breakpoints).toBe(true);
44	  });
45	
46	  describe('idempotency', () => {
47	    const sql = fs.readFileSync(
48	      path.join(DRIZZLE_DIR, MIGRATION_FILE),
49	      'utf-8',
50	    );
51	
52	    it('every CREATE TABLE uses IF NOT EXISTS', () => {
53	      const createTableMatches = sql.match(/CREATE TABLE\b[^;]*/gi) ?? [];
54	      expect(createTableMatches.length).toBeGreaterThan(0);
55	      for (const stmt of createTableMatches) {
56	        expect(stmt).toMatch(/CREATE TABLE\s+IF NOT EXISTS/i);
57	      }
58	    });
59	
60	    it('every CREATE INDEX uses IF NOT EXISTS', () => {
61	      const createIndexMatches =
62	        sql.match(/CREATE\s+(UNIQUE\s+)?INDEX\b[^;]*/gi) ?? [];
63	      expect(createIndexMatches.length).toBeGreaterThan(0);
64	      for (const stmt of createIndexMatches) {
65	        expect(stmt).toMatch(/CREATE\s+(UNIQUE\s+)?INDEX\s+IF NOT EXISTS/i);
66	      }
67	    });
68	
69	    it('seed INSERT uses ON CONFLICT DO NOTHING', () => {
70	      // The seed is wrapped in a DO $$ ... END $$ guard so its absence is
71	      // possible if the spec changes — but if the INSERT is present it must
72	      // be idempotent.
73	      if (/INSERT INTO oauth_clients/i.test(sql)) {
74	        expect(sql).toMatch(
75	          /ON CONFLICT\s*\([^)]*client_id[^)]*\)\s*DO NOTHING/i,
76	        );
77	      }
78	    });
79	
80	    it('declares all five required tables', () => {
81	      for (const table of [
82	        'oauth_clients',
83	        'oauth_authorization_codes',
84	        'oauth_access_tokens',
85	        'oauth_refresh_tokens',
86	        'oauth_audit_log',
87	      ]) {
88	        expect(sql).toMatch(
89	          new RegExp(`CREATE TABLE\\s+IF NOT EXISTS\\s+${table}\\b`, 'i'),
90	        );
91	      }
92	    });
93	
94	    it('declares all required indexes', () => {
95	      for (const idx of [
96	        'oauth_clients_client_id_idx',
97	        'oauth_clients_active_idx',
98	        'oauth_codes_code_hash_idx',
99	        'oauth_codes_expires_idx',
100	        'oauth_access_tokens_hash_idx',
101	        'oauth_access_tokens_org_idx',
102	        'oauth_refresh_tokens_hash_idx',
103	        // Migration 0356 created this index as `oauth_audit_org_idx`. The
104	        // rename to `oauth_audit_school_idx` lands in a subsequent migration
105	        // (W5-3 / DEBT-3 closure); this smoke test pins what 0356 itself
106	        // declared so the pairing test stays anchored to the original SQL.
107	        'oauth_audit_org_idx',
108	      ]) {
109	        expect(sql).toMatch(new RegExp(`\\b${idx}\\b`, 'i'));
110	      }
111	    });
112	
113	    it('scopes tenant rows to flight_schools(id)', () => {
114	      // Every tenant-scoped table references flight_schools(id). This is the
115	      // codebase convention (PDD-002 — multi-tenant isolation enforced at
116	      // the schema level).
117	      const tenantTables = [
118	        'oauth_authorization_codes',
119	        'oauth_access_tokens',
120	        'oauth_refresh_tokens',
121	      ];
122	      for (const table of tenantTables) {
123	        const block = sql.match(
124	          new RegExp(
125	            `CREATE TABLE\\s+IF NOT EXISTS\\s+${table}[\\s\\S]*?\\);`,
126	            'i',
127	          ),
128	        );
129	        expect(block).not.toBeNull();
130	        expect(block?.[0]).toMatch(
131	          /flight_school_id\s+uuid\s+NOT NULL\s+REFERENCES\s+flight_schools\(id\)/i,
132	        );
133	      }
134	    });
135	  });
136	});
