138	describe('drizzle journal pairing audit', () => {
139	  it('every .sql file in drizzle/ has a matching journal tag', () => {
140	    const sqlFiles = fs
141	      .readdirSync(DRIZZLE_DIR)
142	      .filter((f) => f.endsWith('.sql'))
143	      .map((f) => f.replace(/\.sql$/, ''));
144	    const journal = loadJournal();
145	    const tags = new Set(journal.entries.map((e) => e.tag));
146	    const orphans = sqlFiles.filter((f) => !tags.has(f));
147	    expect(orphans).toEqual([]);
148	  });
149	});
